import { describe, expect, it } from 'vitest'

import { crowdinLocales } from '#src/localization-src/generated/constants'
import { languageNames, languageTerritories } from '#src/localization-src/generated/languages'
import {
  isRtlLocale,
  languageFlag,
  languageName,
  languageOptions,
  matchLocale,
  NO_FLAG,
} from '#src/localization-src/languageList'

/**
 * The list and its data come from the submodule, generated by the weekly Crowdin job. The tests
 * live here because that repo has no test runner, and because this is the app that would ship the
 * blank row: Hermes has neither `Intl.DisplayNames` nor `Intl.Locale`, so nothing downstream can
 * work any of it out at runtime.
 */
describe('language names', () => {
  it('covers every locale the app ships', () => {
    const missing = crowdinLocales.filter((l) => !(l in languageNames))
    expect(missing).toEqual([])
  })

  it('names each language in its own language, not in English', () => {
    // The whole point of the table: a picker shows people their language as they write it.
    expect(languageName('fr')).toBe('français')
    expect(languageName('ja')).toBe('日本語')
    expect(languageName('ar')).toBe('العربية')
    expect(languageName('es-419')).toBe('español latinoamericano')
  })

  it('never renders a blank row', () => {
    for (const locale of crowdinLocales) {
      expect(languageName(locale).trim().length, locale).toBeGreaterThan(0)
    }
  })

  it('includes the numeric-region locale a letters-only pattern drops', () => {
    // `es-419` was missed by the first generator and caught by the typecheck rather than by eye.
    expect(languageNames['es-419']).toBeTruthy()
  })

  it('names a catalogue in the language it is written in, not in the one its code names', () => {
    // Four codes say something other than what their strings are: `ku` holds Sorani, `kmr` the
    // Kurmanji CLDR files under `ku`, and of the two Serbian catalogues `sr-CS` is the Latin one.
    // Naming them from the code alone put Latin script on a Sorani row and swapped the two
    // Serbian labels.
    expect(languageName('ku')).toBe('کوردیی ناوەندی')
    expect(languageName('kmr')).toBe('kurdî (kurmancî)')
    expect(languageName('sr-CS')).toBe('srpski (latinica)')
    expect(languageName('sr-SP')).toBe('српски (ћирилица)')
  })
})

describe('language flags', () => {
  it('covers every locale the app ships', () => {
    const missing = crowdinLocales.filter((l) => !(l in languageTerritories))
    expect(missing).toEqual([])
  })

  it('draws a real flag where the language has a country', () => {
    expect(languageFlag('fr')).toBe('🇫🇷')
    expect(languageFlag('ja')).toBe('🇯🇵')
    // Stated by the locale rather than inferred, and the two must not collapse to one flag.
    expect(languageFlag('pt-BR')).toBe('🇧🇷')
    expect(languageFlag('pt-PT')).toBe('🇵🇹')
  })

  it('falls back to the globe for the locales with no country', () => {
    // `001` (World) and `419` (Latin America) are regions rather than countries, and a flag needs
    // a country.
    expect(languageFlag('eo')).toBe(NO_FLAG)
    expect(languageFlag('es-419')).toBe(NO_FLAG)
  })

  it('emits a flag or the globe and never a raw region code', () => {
    for (const locale of crowdinLocales) {
      const flag = languageFlag(locale)
      // A flag is a pair of regional indicators; anything else here would have shipped as text.
      const isFlag = [...flag].every((ch) => {
        const code = ch.codePointAt(0) ?? 0
        return code >= 0x1f1e6 && code <= 0x1f1ff
      })
      expect(isFlag || flag === NO_FLAG, `${locale} -> ${flag}`).toBe(true)
    }
  })
})

describe('mirroring', () => {
  it('mirrors for every Perso-Arabic and Hebrew catalogue we ship', () => {
    // `bal` and `ku` are the two that were missed: Baluchi because Crowdin's project setting has
    // it left-to-right, and `ku` because its catalogue is Sorani rather than the Kurmanji its code
    // names. Both shipped a left-to-right layout to a reader of a right-to-left script.
    for (const locale of ['ar', 'bal', 'fa', 'he', 'ku', 'ps', 'ur'] as const) {
      expect(isRtlLocale(locale), locale).toBe(true)
    }
  })

  it('leaves everything else alone', () => {
    for (const locale of ['en', 'fr', 'ja', 'kmr', 'sr-CS'] as const) {
      expect(isRtlLocale(locale), locale).toBe(false)
    }
  })
})

describe('the picker list', () => {
  it('has a row for every locale', () => {
    expect(languageOptions).toHaveLength(crowdinLocales.length)
  })

  it('is ordered by the name as written, not by locale code', () => {
    const names = languageOptions.map((l) => l.name)
    expect(names).toEqual([...names].sort((a, b) => a.localeCompare(b)))
  })

  it('does not draw two rows with the same name', () => {
    // CLDR treats Tagalog as the old code for Filipino and names both the same unless it is asked
    // about the exact code. The two catalogues are not the same translation -- about 70% of their
    // strings differ -- so two rows reading "Filipino" offered a choice nobody could make.
    const names = languageOptions.map((option) => option.name)
    expect(new Set(names).size).toBe(names.length)
    expect(languageName('tl')).toBe('Tagalog')
    expect(languageName('fil')).toBe('Filipino')
  })

  it('carries an English name wherever that is a different word', () => {
    const japanese = languageOptions.find((option) => option.locale === 'ja')
    expect(japanese?.english).toBe('Japanese')
    // The same word in both: null rather than a repeat, since nothing renders it.
    const esperanto = languageOptions.find((option) => option.locale === 'eo')
    expect(esperanto?.english).toBeNull()
  })
})

describe('matching a device language tag', () => {
  it('prefers the whole tag over its base', () => {
    // Otherwise `pt-BR` silently becomes European Portuguese, which is a different list entry.
    expect(matchLocale('pt-BR')).toBe('pt-BR')
  })

  it('falls back to the base language when the region is not shipped', () => {
    expect(matchLocale('fr-CA')).toBe('fr')
  })

  it('returns null rather than guessing English', () => {
    expect(matchLocale('zz')).toBeNull()
  })

  it('resolves Chinese by script, which is how every platform reports it', () => {
    // The catalogue names Chinese by region, every platform reports it by script, and there is no
    // bare `zh` to fall back to -- so this matched nothing and the app stayed in English for
    // anybody whose language was Chinese. `zh-Hans-AU` is what iOS reports when the app's language
    // is Simplified Chinese on an Australian device.
    expect(matchLocale('zh-Hans')).toBe('zh-CN')
    expect(matchLocale('zh-Hant')).toBe('zh-TW')
    expect(matchLocale('zh-Hans-AU')).toBe('zh-CN')
    expect(matchLocale('zh-Hant-TW')).toBe('zh-TW')
  })

  it('truncates one subtag at a time rather than jumping to the base', () => {
    expect(matchLocale('pt-BR-u-ca-gregory')).toBe('pt-BR')
  })

  it('takes a language with exactly one shipped variant', () => {
    expect(matchLocale('hy')).toBe('hy-AM')
  })

  it('refuses to choose between two variants of the same language', () => {
    // `pt` could be either Portuguese. Picking one would be inventing an answer the tag did not
    // give, and the caller has a better fallback than a guess.
    expect(matchLocale('pt')).toBeNull()
    expect(matchLocale('zh')).toBeNull()
  })
})
